import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Container, Typography, TextField, Button, Grid, Box, 
  Paper, FormControl, InputLabel, Select, MenuItem, 
  CircularProgress, Alert, FormHelperText
} from '@mui/material';
import { styled } from '@mui/material/styles';
import { useForm, Controller } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import { 
  Search, LocationOn, CalendarToday, ShoppingBag, 
  MonetizationOn, Description
} from '@mui/icons-material';
import { auth, db } from '../firebase';
import { collection, addDoc, serverTimestamp } from 'firebase/firestore';

// Styled components
const RequestContainer = styled(Container)(({ theme }) => ({
  marginTop: theme.spacing(4),
  marginBottom: theme.spacing(8),
  padding: theme.spacing(4)
}));

const FormPaper = styled(Paper)(({ theme }) => ({
  padding: theme.spacing(4),
  borderRadius: theme.spacing(2),
  boxShadow: '0 8px 24px rgba(0, 0, 0, 0.12)'
}));

const FormTitle = styled(Typography)(({ theme }) => ({
  fontWeight: 700,
  marginBottom: theme.spacing(1),
  color: theme.palette.primary.main,
  '& span': {
    color: theme.palette.secondary.main
  }
}));

const FormSubtitle = styled(Typography)(({ theme }) => ({
  marginBottom: theme.spacing(4),
  color: theme.palette.text.secondary
}));

const StyledTextField = styled(TextField)(({ theme }) => ({
  marginBottom: theme.spacing(3)
}));

const StyledFormControl = styled(FormControl)(({ theme }) => ({
  marginBottom: theme.spacing(3)
}));

const SubmitButton = styled(Button)(({ theme }) => ({
  marginTop: theme.spacing(2),
  padding: theme.spacing(1.5, 4),
  borderRadius: theme.spacing(3),
  fontSize: '1rem',
  textTransform: 'none',
  boxShadow: '0 4px 12px rgba(0, 0, 0, 0.15)',
  '&:hover': {
    boxShadow: '0 6px 16px rgba(0, 0, 0, 0.2)',
  }
}));

// Form validation schema
const schema = yup.object().shape({
  item_name: yup.string().required('Item name is required'),
  item_description: yup.string().required('Item description is required'),
  item_location: yup.string().required('Item location is required'),
  delivery_location: yup.string().required('Delivery location is required'),
  needed_by_date: yup.date()
    .required('Delivery date is required')
    .min(new Date(), 'Date must be in the future'),
  item_size: yup.string().required('Item size is required'),
  item_weight: yup.number()
    .required('Item weight is required')
    .positive('Weight must be positive')
    .typeError('Weight must be a number'),
  offer_price: yup.number()
    .required('Offer amount is required')
    .min(5, 'Minimum offer is $5')
    .typeError('Offer must be a number'),
  additional_notes: yup.string()
});

const RequestItem = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);
  
  const { control, handleSubmit, reset, formState: { errors } } = useForm({
    resolver: yupResolver(schema),
    defaultValues: {
      item_name: '',
      item_description: '',
      item_location: '',
      delivery_location: '',
      needed_by_date: '',
      item_size: '',
      item_weight: '',
      offer_price: '',
      additional_notes: ''
    }
  });

  const onSubmit = async (data) => {
    setLoading(true);
    setError(null);
    
    try {
      // Get current user
      const user = auth.currentUser;
      
      if (!user) {
        throw new Error('You must be logged in to request an item');
      }
      
      // Add the item request to Firestore
      const itemRequestsRef = collection(db, 'item_requests');
      await addDoc(itemRequestsRef, {
        userId: user.uid,
        email: user.email,
        item_name: data.item_name,
        item_description: data.item_description,
        item_location: data.item_location,
        delivery_location: data.delivery_location,
        needed_by_date: data.needed_by_date,
        item_size: data.item_size,
        item_weight: data.item_weight,
        offer_price: data.offer_price,
        additional_notes: data.additional_notes || '',
        status: 'open',
        created_at: serverTimestamp()
      });
      
      // Success
      setSuccess(true);
      
      // Reset form
      reset();
      
      // Redirect to dashboard after 2 seconds
      setTimeout(() => {
        navigate('/dashboard');
      }, 2000);
      
    } catch (err) {
      console.error("Error adding item request:", err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <RequestContainer maxWidth="md">
      <FormPaper elevation={3}>
        <FormTitle variant="h4" component="h1" gutterBottom>
          Request an item from <span>Anywhere in the World</span>
        </FormTitle>
        
        <FormSubtitle variant="body1" gutterBottom>
          Tell us what you need, where it is from, and where you want it delivered. We'll connect you with travelers who can help.
        </FormSubtitle>
        
        {error && (
          <Alert severity="error" sx={{ mb: 3 }}>
            {error}
          </Alert>
        )}
        
        {success && (
          <Alert severity="success" sx={{ mb: 3 }}>
            Your item request has been submitted successfully! Redirecting to dashboard...
          </Alert>
        )}
        
        <form onSubmit={handleSubmit(onSubmit)}>
          <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
              <Controller
                name="item_name"
                control={control}
                render={({ field }) => (
                  <StyledTextField
                    {...field}
                    label="Item Name"
                    placeholder="What do you need?"
                    fullWidth
                    error={!!errors.item_name}
                    helperText={errors.item_name?.message || ""}
                    InputProps={{
                      startAdornment: (
                        <Search sx={{ mr: 1, color: 'primary.main' }} />
                      ),
                    }}
                  />
                )}
              />
            </Grid>
            
            <Grid item xs={12} md={6}>
              <Controller
                name="item_location"
                control={control}
                render={({ field }) => (
                  <StyledTextField
                    {...field}
                    label="Where is the item located?"
                    placeholder="City, Country"
                    fullWidth
                    error={!!errors.item_location}
                    helperText={errors.item_location?.message || ""}
                    InputProps={{
                      startAdornment: (
                        <LocationOn sx={{ mr: 1, color: 'primary.main' }} />
                      ),
                    }}
                  />
                )}
              />
            </Grid>
            
            <Grid item xs={12}>
              <Controller
                name="item_description"
                control={control}
                render={({ field }) => (
                  <StyledTextField
                    {...field}
                    label="Provide details about the item"
                    placeholder="Describe the item, brand, model, etc."
                    fullWidth
                    multiline
                    rows={3}
                    error={!!errors.item_description}
                    helperText={errors.item_description?.message || ""}
                    InputProps={{
                      startAdornment: (
                        <Description sx={{ mr: 1, mt: 1, color: 'primary.main' }} />
                      ),
                    }}
                  />
                )}
              />
            </Grid>
            
            <Grid item xs={12} md={6}>
              <Controller
                name="delivery_location"
                control={control}
                render={({ field }) => (
                  <StyledTextField
                    {...field}
                    label="Delivery Location"
                    placeholder="Where do you want it delivered?"
                    fullWidth
                    error={!!errors.delivery_location}
                    helperText={errors.delivery_location?.message || ""}
                    InputProps={{
                      startAdornment: (
                        <LocationOn sx={{ mr: 1, color: 'secondary.main' }} />
                      ),
                    }}
                  />
                )}
              />
            </Grid>
            
            <Grid item xs={12} md={6}>
              <Controller
                name="needed_by_date"
                control={control}
                render={({ field }) => (
                  <StyledTextField
                    {...field}
                    type="date"
                    label="Needed By Date"
                    InputLabelProps={{ shrink: true }}
                    fullWidth
                    error={!!errors.needed_by_date}
                    helperText={errors.needed_by_date?.message || ""}
                    InputProps={{
                      startAdornment: (
                        <CalendarToday sx={{ mr: 1, color: 'secondary.main' }} />
                      ),
                    }}
                  />
                )}
              />
            </Grid>
            
            <Grid item xs={12} md={4}>
              <Controller
                name="item_size"
                control={control}
                render={({ field }) => (
                  <StyledFormControl fullWidth error={!!errors.item_size}>
                    <InputLabel id="item-size-label">Item Size</InputLabel>
                    <Select
                      {...field}
                      labelId="item-size-label"
                      label="Item Size"
                      startAdornment={<ShoppingBag sx={{ mr: 1, color: 'primary.main' }} />}
                    >
                      <MenuItem value="small">Small (fits in a handbag)</MenuItem>
                      <MenuItem value="medium">Medium (shoebox size)</MenuItem>
                      <MenuItem value="large">Large (backpack size)</MenuItem>
                      <MenuItem value="extra_large">Extra Large (suitcase size)</MenuItem>
                    </Select>
                    {errors.item_size && <FormHelperText>{errors.item_size.message}</FormHelperText>}
                  </StyledFormControl>
                )}
              />
            </Grid>
            
            <Grid item xs={12} md={4}>
              <Controller
                name="item_weight"
                control={control}
                render={({ field }) => (
                  <StyledTextField
                    {...field}
                    label="Weight (kg)"
                    type="number"
                    fullWidth
                    InputProps={{ 
                      inputProps: { min: 0, step: 0.1 },
                      startAdornment: (
                        <ShoppingBag sx={{ mr: 1, color: 'secondary.main' }} />
                      ),
                    }}
                    error={!!errors.item_weight}
                    helperText={errors.item_weight?.message || ""}
                  />
                )}
              />
            </Grid>
            
            <Grid item xs={12} md={4}>
              <Controller
                name="offer_price"
                control={control}
                render={({ field }) => (
                  <StyledTextField
                    {...field}
                    label="Your Offer ($)"
                    type="number"
                    fullWidth
                    InputProps={{ 
                      inputProps: { min: 5, step: 1 },
                      startAdornment: (
                        <MonetizationOn sx={{ mr: 1, color: 'secondary.main' }} />
                      ),
                    }}
                    error={!!errors.offer_price}
                    helperText={errors.offer_price?.message || ""}
                  />
                )}
              />
            </Grid>
            
            <Grid item xs={12}>
              <Controller
                name="additional_notes"
                control={control}
                render={({ field }) => (
                  <StyledTextField
                    {...field}
                    label="Additional Notes (Optional)"
                    placeholder="Any special instructions or requirements"
                    fullWidth
                    multiline
                    rows={2}
                    error={!!errors.additional_notes}
                    helperText={errors.additional_notes?.message || ""}
                  />
                )}
              />
            </Grid>
            
            <Grid item xs={12} sx={{ textAlign: 'center' }}>
              <SubmitButton
                type="submit"
                variant="contained"
                color="primary"
                size="large"
                disabled={loading}
                startIcon={loading ? <CircularProgress size={20} color="inherit" /> : null}
              >
                {loading ? 'Submitting Request...' : 'Submit Request'}
              </SubmitButton>
            </Grid>
          </Grid>
        </form>
      </FormPaper>
    </RequestContainer>
  );
};

export default RequestItem;