// Analytics tracker component
function PageViewTracker() {
  const location = useLocation();
  
  useEffect(() => {
    // Track page view on location change
    trackPageView(
      location.pathname + location.search,
      document.title
    );
  }, [location]);
  
  return null;
}

function App() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [firebaseConnected, setFirebaseConnected] = useState(false);

  // Determine the base URL for router
  const basename = process.env.NODE_ENV === 'production' 
    ? window.location.pathname.includes('global-pickups') 
      ? '/global-pickups' 
      : '/'
    : '/';

  useEffect(() => {
    // If mock API is enabled, use a mock user or set loading to false directly
    if (useMockApi) {
      setLoading(false);
      return;
    }
    
    // Set up Firebase auth state listener
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser) {
        // User is signed in
        try {
          // Fetch user profile data from Firestore
          const userDocRef = doc(db, "profiles", firebaseUser.uid);
          const userDocSnap = await getDoc(userDocRef);
          
          if (userDocSnap.exists()) {
            // Combine Firestore profile data with auth user data
            const profileData = userDocSnap.data();
            setUser({
              ...profileData,
              id: firebaseUser.uid,
              email: firebaseUser.email,
              emailVerified: firebaseUser.emailVerified
            });
            
            // Set anonymized user properties for analytics
            setUserProperties(firebaseUser.uid, {
              user_type: profileData.role || 'standard',
              account_created: profileData.created_at,
              account_status: firebaseUser.emailVerified ? 'verified' : 'unverified'
            });
          } else {
            // Just use the basic Firebase auth user if no profile exists
            setUser({
              id: firebaseUser.uid,
              email: firebaseUser.email,
              emailVerified: firebaseUser.emailVerified
            });
          }
        } catch (error) {
          console.error("Error fetching user profile:", error);
          setUser({
            id: firebaseUser.uid,
            email: firebaseUser.email,
            emailVerified: firebaseUser.emailVerified
          });
        }
      } else {
        // User is signed out
        setUser(null);
      }
      setLoading(false);
    });
    
    // Clean up subscription on unmount
    return () => unsubscribe();
  }, []);

  // Test Firebase connection
  useEffect(() => {
    const testFirebaseConnection = async () => {
      try {
        // Try to get a document from Firestore
        const querySnapshot = await getDocs(collection(db, "test_collection"));
        console.log("Firebase connection successful", querySnapshot);
        setFirebaseConnected(true);
      } catch (error) {
        console.error("Firebase connection error:", error);
        setFirebaseConnected(false);
      }
    };
    
    testFirebaseConnection();
  }, []);

  const handleLogout = async () => {
    if (useMockApi) {
      setUser(null);
      return;
    }
    
    try {
      await signOut(auth);
      setUser(null);
    } catch (error) {
      console.error("Error signing out: ", error);
    }
  };

  // Simple route protection component
  const ProtectedRoute = ({ children }) => {
    if (loading) return <div>Loading...</div>;
    
    // In mock API mode, allow access to protected routes for testing
    if (useMockApi && !user) {
      return children;
    }
    
    if (!user) return <Navigate to="/login" replace />;
    return children;
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Router basename={basename}>
        <PageViewTracker />
        <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
          <NavBar />
          
          <Box component="main" sx={{ flexGrow: 1 }}>
            <Routes>
              <Route path="/" element={
                user ? <Navigate to="/dashboard" replace /> : <LandingPage />
              } />
              
              <Route path="/dashboard" element={
                <ProtectedRoute>
                  <Dashboard />
                </ProtectedRoute>
              } />
              
              <Route path="/login" element={
                user ? <Navigate to="/dashboard" replace /> : <Login />
              } />
              
              <Route path="/signup" element={
                user ? <Navigate to="/dashboard" replace /> : <SignUp />
              } />
              
              <Route path="/verification" element={<VerificationPage />} />
              
              <Route path="/about" element={<About />} />
              
              <Route path="/faq" element={<FAQ />} />
              
              <Route path="/services" element={<Services />} />
              
              <Route path="/pricing" element={<Pricing />} />
              
              <Route path="/privacy" element={<Privacy />} />
              
              <Route path="/add-travel-plan" element={
                <ProtectedRoute>
                  <AddTravelPlan />
                </ProtectedRoute>
              } />
              
              <Route path="/request-item" element={
                <ProtectedRoute>
                  <RequestItem />
                </ProtectedRoute>
              } />
              
              <Route path="/travel-request" element={
                <ProtectedRoute>
                  <TravelAndRequestTabs />
                </ProtectedRoute>
              } />
              
              <Route path="/travel-plans" element={
                <ProtectedRoute>
                  <div>Travel Plans Page (Coming Soon)</div>
                </ProtectedRoute>
              } />
              
              <Route path="/item-requests" element={
                <ProtectedRoute>
                  <div>Item Requests Page (Coming Soon)</div>
                </ProtectedRoute>
              } />
              
              <Route path="/messages" element={
                <ProtectedRoute>
                  <div>Messages Page (Coming Soon)</div>
                </ProtectedRoute>
              } />
              
              <Route path="/profile" element={
                <ProtectedRoute>
                  <div>Profile Page (Coming Soon)</div>
                </ProtectedRoute>
              } />
              
              <Route path="/settings" element={
                <ProtectedRoute>
                  <div>Settings Page (Coming Soon)</div>
                </ProtectedRoute>
              } />
              
              <Route path="*" element={<div>Page Not Found</div>} />
            </Routes>
          </Box>
          
          {/* Cookie Consent Banner */}
          <CookieConsent />
        </Box>
      </Router>
    </ThemeProvider>
  );
}

export default App;