import React, { useState, useEffect } from 'react';
import { 
  Box, Typography, Button, Snackbar, Paper,
  Dialog, DialogTitle, DialogContent, DialogActions,
  Checkbox, FormControlLabel, Link
} from '@mui/material';
import { Close, Cookie } from '@mui/icons-material';
import { updateConsentStatus } from '../../utils/analytics';

const CookieConsent = () => {
  const [open, setOpen] = useState(false);
  const [showAdvanced, setShowAdvanced] = useState(false);
  const [settings, setSettings] = useState({
    necessary: true, // Always required
    analytics: true,
    marketing: false
  });

  useEffect(() => {
    // Check if user has already made a choice
    const consentStatus = localStorage.getItem('analytics-consent');
    
    if (consentStatus === null) {
      // No decision made yet, show the banner
      setOpen(true);
    }
  }, []);

  const handleAcceptAll = () => {
    // Save preferences
    localStorage.setItem('analytics-consent', 'true');
    updateConsentStatus(true);
    setOpen(false);
  };

  const handleRejectAll = () => {
    // Save preferences
    localStorage.setItem('analytics-consent', 'false');
    updateConsentStatus(false);
    setOpen(false);
  };

  const handleSavePreferences = () => {
    // Save preferences based on analytics checkbox
    localStorage.setItem('analytics-consent', settings.analytics.toString());
    updateConsentStatus(settings.analytics);
    setOpen(false);
  };

  const handleCheckboxChange = (event) => {
    setSettings({
      ...settings,
      [event.target.name]: event.target.checked
    });
  };

  if (!open) return null;

  return (
    <>
      {/* Simple banner for initial display */}
      <Snackbar
        open={open && !showAdvanced}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Paper 
          elevation={3} 
          sx={{ 
            p: 2, 
            width: '100%', 
            maxWidth: 600, 
            display: 'flex', 
            alignItems: 'center', 
            gap: 2,
            borderRadius: 2,
            border: '1px solid rgba(109, 142, 197, 0.2)',
          }}
        >
          <Cookie color="primary" />
          <Typography variant="body2" sx={{ flex: 1 }}>
            We use cookies to enhance your experience and analyze our site performance. 
            Would you like to accept analytics cookies?
          </Typography>
          <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', justifyContent: 'flex-end' }}>
            <Button 
              size="small" 
              onClick={() => setShowAdvanced(true)} 
              variant="text"
            >
              Preferences
            </Button>
            <Button 
              size="small" 
              onClick={handleRejectAll} 
              variant="outlined" 
              color="secondary"
            >
              Reject
            </Button>
            <Button 
              size="small" 
              onClick={handleAcceptAll} 
              variant="contained" 
              color="primary"
            >
              Accept
            </Button>
          </Box>
        </Paper>
      </Snackbar>

      {/* Advanced dialog for cookie preferences */}
      <Dialog 
        open={showAdvanced} 
        onClose={() => setShowAdvanced(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>
          Cookie Preferences
          <Button 
            onClick={() => setShowAdvanced(false)} 
            sx={{ position: 'absolute', right: 8, top: 8 }}
          >
            <Close />
          </Button>
        </DialogTitle>
        <DialogContent>
          <Typography paragraph variant="body2">
            We use cookies to ensure the website functions properly, enhance your experience, 
            and analyze our performance. You can choose which categories of cookies you allow.
          </Typography>
          
          <Box sx={{ my: 2 }}>
            <FormControlLabel
              control={
                <Checkbox checked={settings.necessary} disabled />
              }
              label={
                <Box>
                  <Typography variant="subtitle2">Necessary Cookies</Typography>
                  <Typography variant="caption" color="text.secondary">
                    Essential for the basic functions of the website. The website cannot function properly without these cookies.
                  </Typography>
                </Box>
              }
            />
          </Box>
          
          <Box sx={{ my: 2 }}>
            <FormControlLabel
              control={
                <Checkbox 
                  checked={settings.analytics} 
                  onChange={handleCheckboxChange}
                  name="analytics"
                />
              }
              label={
                <Box>
                  <Typography variant="subtitle2">Analytics Cookies</Typography>
                  <Typography variant="caption" color="text.secondary">
                    Help us understand how visitors interact with our website by collecting and reporting anonymous information.
                  </Typography>
                </Box>
              }
            />
          </Box>
          
          <Box sx={{ my: 2 }}>
            <FormControlLabel
              control={
                <Checkbox 
                  checked={settings.marketing} 
                  onChange={handleCheckboxChange}
                  name="marketing"
                />
              }
              label={
                <Box>
                  <Typography variant="subtitle2">Marketing Cookies</Typography>
                  <Typography variant="caption" color="text.secondary">
                    Used to track visitors across websites to display relevant advertisements.
                  </Typography>
                </Box>
              }
            />
          </Box>
          
          <Typography variant="caption" paragraph>
            For more information about how we use cookies, please see our <Link href="/privacy" color="primary">Privacy Policy</Link>.
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleRejectAll} color="secondary">
            Reject All
          </Button>
          <Button onClick={handleAcceptAll} color="success">
            Accept All
          </Button>
          <Button onClick={handleSavePreferences} variant="contained" color="primary">
            Save Preferences
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default CookieConsent;