import React, { useState, useEffect } from 'react';
import { 
  Box, Typography, Grid, Card, CardContent, CardActions,
  Button, Avatar, Chip, CircularProgress, Alert,
  Container, Paper, Divider, Tooltip, IconButton,
  Dialog, DialogTitle, DialogContent, DialogContentText,
  DialogActions, useTheme, useMediaQuery
} from '@mui/material';
import { 
  Flight, LocalShipping, Star, AdminPanelSettings, 
  ArrowBack, Add, DateRange, LocationOn, Scale, 
  CardTravel, Schedule, InfoOutlined, ArrowForward,
  AddCircleOutline, NoteAdd
} from '@mui/icons-material';
import { supabase } from '../supabase';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import SearchBar from './SearchBar';
import OnboardingTour from './shared/Onboarding/OnboardingTour';
import { dashboardTourSteps } from './shared/Onboarding';
import { auth, db } from '../firebase';
import { collection, query, where, getDocs } from 'firebase/firestore';
import { formatDistanceToNow } from 'date-fns';

const Dashboard = () => {
  const [userProfile, setUserProfile] = useState(null);
  const [travelPlans, setTravelPlans] = useState([]);
  const [itemRequests, setItemRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState(false);
  const [searchResults, setSearchResults] = useState(null);
  const [searchType, setSearchType] = useState(null);
  const [searchCriteria, setSearchCriteria] = useState(null);
  const [runTour, setRunTour] = useState(false);
  const [openGuideDialog, setOpenGuideDialog] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        setLoading(true);
        
        if (location.state?.searchResults && location.state?.searchType) {
          setSearchResults(location.state.searchResults);
          setSearchType(location.state.searchType);
          setLoading(false);
          return;
        }
        
        const storedSearchResults = localStorage.getItem('searchResults');
        if (storedSearchResults) {
          const parsedResults = JSON.parse(storedSearchResults);
          setSearchResults(parsedResults.results);
          setSearchType(parsedResults.type);
          setSearchCriteria(parsedResults.criteria);
          setLoading(false);
          return;
        }
        
        const adminUser = localStorage.getItem('adminUser');
        if (adminUser) {
          const parsedAdminUser = JSON.parse(adminUser);
          setUserProfile({
            id: parsedAdminUser.id,
            full_name: parsedAdminUser.name,
            avatar_url: null,
            bio: 'Admin account for testing and management',
            rating: 5.0,
            verified: true
          });
          setIsAdmin(true);
          setLoading(false);
          return;
        }
        
        // Try to use Firebase first
        try {
          const user = auth.currentUser;
          
          if (user) {
            // Fetch user profile from Firestore
            const userDocRef = collection(db, "profiles");
            const q = query(userDocRef, where("email", "==", user.email));
            const querySnapshot = await getDocs(q);
            
            if (!querySnapshot.empty) {
              const profileData = querySnapshot.docs[0].data();
              
              setUserProfile({
                id: user.uid,
                full_name: `${profileData.firstName} ${profileData.lastName}`,
                avatar_url: profileData.photoURL || null,
                bio: profileData.bio || 'No bio yet',
                rating: profileData.rating || 4.8,
                verified: user.emailVerified
              });
              
              // Fetch travel plans from Firestore
              const travelPlansRef = collection(db, "travel_plans");
              const travelPlansQuery = query(travelPlansRef, where("userId", "==", user.uid));
              const travelPlansSnapshot = await getDocs(travelPlansQuery);
              
              const travelPlansData = travelPlansSnapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data()
              }));
              
              setTravelPlans(travelPlansData);
              
              // Fetch item requests from Firestore
              const itemRequestsRef = collection(db, "item_requests");
              const itemRequestsQuery = query(itemRequestsRef, where("userId", "==", user.uid));
              const itemRequestsSnapshot = await getDocs(itemRequestsQuery);
              
              const itemRequestsData = itemRequestsSnapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data()
              }));
              
              setItemRequests(itemRequestsData);
            }
          }
        } catch (firebaseError) {
          console.error('Firebase error, falling back to Supabase:', firebaseError);
          
          // Fall back to Supabase if Firebase fails
          const { data: { user } } = await supabase.auth.getUser();
          
          if (!user) {
            throw new Error('No user logged in');
          }

          const { data: profileData, error: profileError } = await supabase
            .from('profiles')
            .select('*')
            .eq('id', user.id)
            .single();
          
          if (profileError) throw profileError;
          
          const profile = profileData || {
            id: user.id,
            full_name: user.user_metadata?.full_name || 'New User',
            avatar_url: null,
            bio: 'No bio yet',
            rating: 0,
            verified: false
          };
          
          setUserProfile(profile);
          
          const { data: travelPlansData, error: travelPlansError } = await supabase
            .from('travel_plans')
            .select('*')
            .eq('user_id', user.id)
            .order('departure_date', { ascending: true });
          
          if (travelPlansError) throw travelPlansError;
          
          setTravelPlans(travelPlansData || []);
          
          const { data: itemRequestsData, error: itemRequestsError } = await supabase
            .from('item_requests')
            .select(`
              *,
              requester:profiles(full_name, avatar_url, rating)
            `)
            .eq('user_id', user.id)
            .order('deadline', { ascending: true });
          
          if (itemRequestsError) throw itemRequestsError;
          
          setItemRequests(itemRequestsData || []);
        }
      } catch (error) {
        console.error('Error fetching dashboard data:', error);
      } finally {
        setLoading(false);
      }
    };

    const checkFirstVisit = () => {
      const hasSeenTour = localStorage.getItem('hasSeenDashboardTour');
      if (!hasSeenTour && !searchResults) {
        setTimeout(() => {
          setRunTour(true);
          localStorage.setItem('hasSeenDashboardTour', 'true');
        }, 1000);
      }
    };
    
    fetchDashboardData();
    checkFirstVisit();
  }, [location, searchResults]);

  const handleTourClose = () => {
    setRunTour(false);
  };

  const handleLogout = () => {
    localStorage.removeItem('adminUser');
    localStorage.removeItem('searchResults');
    supabase.auth.signOut();
    navigate('/');
  };

  const clearSearchResults = () => {
    setSearchResults(null);
    setSearchType(null);
    setSearchCriteria(null);
    localStorage.removeItem('searchResults');
    navigate('/dashboard', { replace: true });
  };

  const handleAddTravelPlan = () => {
    navigate('/add-travel-plan');
  };

  const handleAddItemRequest = () => {
    navigate('/request-item');
  };

  const handleOpenGuide = () => {
    setOpenGuideDialog(true);
  };

  const handleCloseGuide = () => {
    setOpenGuideDialog(false);
  };
  
  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh' }}>
        <CircularProgress />
      </Box>
    );
  }
  
  const displayProfile = userProfile || {
    id: 'user-123',
    full_name: 'Belal Sajal',
    avatar_url: 'https://randomuser.me/api/portraits/men/32.jpg',
    rating: 4.8,
    bio: 'Frequent traveler between Asia and Europe. Happy to help bring items to fellow travelers!',
    verified: true
  };
  
  const displayTravelPlans = travelPlans.length > 0 ? travelPlans : [
    {
      id: 'trip-1',
      departure_location: 'Tokyo, Japan',
      destination: 'London, UK',
      departure_date: '2025-04-15',
      arrival_date: '2025-04-16',
      max_weight: 5,
      max_dimensions: '30x20x10 cm'
    },
    {
      id: 'trip-2',
      departure_location: 'London, UK',
      destination: 'New York, USA',
      departure_date: '2025-05-10',
      arrival_date: '2025-05-10',
      max_weight: 3,
      max_dimensions: '25x15x8 cm'
    }
  ];
  
  const displayItemRequests = itemRequests.length > 0 ? itemRequests : [
    {
      id: 'req-1',
      item_name: 'Japanese Snack Box',
      source_location: 'Tokyo, Japan',
      destination_location: 'London, UK',
      deadline: '2025-04-20',
      status: 'open',
      requester: {
        full_name: 'Emma Wilson',
        avatar_url: 'https://randomuser.me/api/portraits/women/23.jpg',
        rating: 4.9
      }
    }
  ];

  if (searchResults) {
    const formatCriteriaText = () => {
      const parts = [];
      if (searchCriteria?.from) parts.push(`from "${searchCriteria.from}"`);
      if (searchCriteria?.to) parts.push(`to "${searchCriteria.to}"`);
      if (searchCriteria?.date) {
        const date = new Date(searchCriteria.date).toLocaleDateString();
        parts.push(`on/before ${date}`);
      }
      if (searchCriteria?.weight) parts.push(`with weight ${searchCriteria.weight}kg`);
      
      return parts.length > 0 
        ? parts.join(' ')
        : 'with your criteria';
    };

    return (
      <Box sx={{ p: 3 }}>
        <OnboardingTour 
          steps={dashboardTourSteps} 
          run={runTour} 
          onClose={handleTourClose}
        />
        
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
          <Button 
            startIcon={<ArrowBack />} 
            variant="outlined" 
            onClick={clearSearchResults}
          >
            Back to Dashboard
          </Button>
          <Button variant="outlined" color="primary" onClick={handleLogout}>
            Logout
          </Button>
        </Box>

        <Alert severity="info" sx={{ mb: 3 }}>
          Showing search results {formatCriteriaText()}
        </Alert>
        
        <Typography variant="h5" gutterBottom>
          {searchType === 'travelers' 
            ? <><Flight sx={{ mr: 1, verticalAlign: 'middle' }} />Travelers Matching Your Search</>
            : <><LocalShipping sx={{ mr: 1, verticalAlign: 'middle' }} />Item Requests Matching Your Search</>
          }
        </Typography>
        
        {searchResults.length === 0 ? (
          <Alert severity="warning" sx={{ mt: 2 }}>
            No results found matching your search criteria. Try broadening your search.
          </Alert>
        ) : (
          <Grid container spacing={3}>
            {/* ... existing search results display code ... */}
          </Grid>
        )}
      </Box>
    );
  }

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      <OnboardingTour 
        steps={dashboardTourSteps} 
        run={runTour} 
        onClose={handleTourClose}
      />
      
      {/* Header with Welcome and Logout */}
      <Box sx={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center', 
        mb: 4,
        flexDirection: isMobile ? 'column' : 'row', 
        gap: isMobile ? 2 : 0 
      }}>
        <Typography variant="h4" component="h1" data-tour="welcome">
          Welcome, {displayProfile.full_name}!
        </Typography>
        <Button 
          variant="outlined" 
          color="primary" 
          onClick={handleLogout}
          sx={{ alignSelf: isMobile ? 'flex-end' : 'center' }}
        >
          Logout
        </Button>
      </Box>

      {/* Profile Card */}
      <Card sx={{ mb: 4 }} data-tour="profile">
        <CardContent>
          <Grid container spacing={2} alignItems="center">
            <Grid item>
              <Avatar 
                src={displayProfile.avatar_url} 
                alt={displayProfile.full_name}
                sx={{ width: 80, height: 80 }}
              />
            </Grid>
            <Grid item xs>
              <Typography variant="h6">
                {displayProfile.full_name}
                {displayProfile.verified && (
                  <Chip 
                    size="small" 
                    label="Verified" 
                    color="primary" 
                    sx={{ ml: 1 }}
                  />
                )}
                {isAdmin && (
                  <Chip 
                    size="small" 
                    label="Admin" 
                    color="secondary" 
                    icon={<AdminPanelSettings fontSize="small" />}
                    sx={{ ml: 1 }}
                  />
                )}
              </Typography>
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                <Star sx={{ color: 'gold', mr: 0.5 }} />
                <Typography variant="body2">
                  {displayProfile.rating} / 5.0 rating
                </Typography>
              </Box>
              <Typography variant="body2" color="text.secondary">
                {displayProfile.bio}
              </Typography>
            </Grid>
          </Grid>
        </CardContent>
      </Card>
      
      {/* Quick Action Buttons */}
      <Paper 
        elevation={1} 
        sx={{ 
          mb: 5, 
          p: 3, 
          borderRadius: 2,
          background: 'linear-gradient(145deg, #ffffff, #f0f7ff)' 
        }}
      >
        <Typography variant="h5" gutterBottom sx={{ mb: 3 }}>
          Create New:
        </Typography>
        <Grid container spacing={3} sx={{ mb: 2 }}>
          <Grid item xs={12} sm={6}>
            <Button
              variant="contained"
              color="primary"
              fullWidth
              size="large"
              startIcon={<Flight />}
              onClick={handleAddTravelPlan}
              sx={{ 
                py: 2, 
                fontSize: '1.1rem',
                background: 'linear-gradient(90deg, #6d8ec5 0%, #5775aa 100%)',
                '&:hover': {
                  background: 'linear-gradient(90deg, #5775aa 0%, #486090 100%)',
                }
              }}
            >
              Add Travel Plan
            </Button>
            <Typography variant="body2" color="text.secondary" sx={{ mt: 1, textAlign: 'center' }}>
              Traveling soon? Share your journey
            </Typography>
          </Grid>
          <Grid item xs={12} sm={6}>
            <Button
              variant="contained"
              color="secondary"
              fullWidth
              size="large"
              startIcon={<LocalShipping />}
              onClick={handleAddItemRequest}
              sx={{ 
                py: 2, 
                fontSize: '1.1rem',
                background: 'linear-gradient(90deg, #d3622c 0%, #b14c1e 100%)',
                '&:hover': {
                  background: 'linear-gradient(90deg, #b14c1e 0%, #913e18 100%)',
                }
              }}
            >
              Create Item Request
            </Button>
            <Typography variant="body2" color="text.secondary" sx={{ mt: 1, textAlign: 'center' }}>
              Need something delivered? Post a request
            </Typography>
          </Grid>
        </Grid>
      </Paper>
      
      {/* Search Section */}
      <Box sx={{ mb: 5 }} data-tour="search">
        <Paper elevation={1} sx={{ p: 3, borderRadius: 2 }}>
          <Typography variant="h5" gutterBottom>Find Travelers or Requests</Typography>
          <SearchBar />
          <Box sx={{ mt: 2, display: 'flex', justifyContent: 'center' }}>
            <Button 
              variant="outlined" 
              color="info"
              startIcon={<InfoOutlined />}
              onClick={handleOpenGuide}
              size="small"
              sx={{ mt: 1 }}
            >
              How to find the perfect match?
            </Button>
          </Box>
        </Paper>
      </Box>
      
      {/* Your Travel Plans */}
      <Box sx={{ mb: 5 }} data-tour="travel-plans">
        <Box sx={{ 
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'center',
          mb: 2
        }}>
          <Typography variant="h5">
            <Flight sx={{ mr: 1, verticalAlign: 'middle' }} />
            Your Travel Plans
          </Typography>
          <Button 
            variant="outlined" 
            color="primary" 
            startIcon={<Add />}
            component={Link}
            to="/add-travel-plan"
            size="small"
          >
            Add New Trip
          </Button>
        </Box>
        
        <Divider sx={{ mb: 3 }} />
        
        {displayTravelPlans.length === 0 ? (
          <Paper
            elevation={0}
            sx={{
              p: 3,
              textAlign: 'center',
              backgroundColor: 'rgba(109, 142, 197, 0.08)',
              borderRadius: 2,
              border: '1px dashed #6d8ec5'
            }}
          >
            <AddCircleOutline sx={{ fontSize: 60, color: 'text.secondary', mb: 1, opacity: 0.7 }} />
            <Typography variant="h6" color="text.secondary" gutterBottom>
              No Travel Plans Yet
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
              Share your travel details with other users who might need items delivered
            </Typography>
            <Button
              variant="contained"
              color="primary"
              startIcon={<Add />}
              onClick={handleAddTravelPlan}
            >
              Add Your First Trip
            </Button>
          </Paper>
        ) : (
          <Grid container spacing={3}>
            {displayTravelPlans.map((plan) => (
              <Grid item xs={12} md={6} key={plan.id}>
                <Card sx={{ height: '100%' }}>
                  <CardContent>
                    <Box sx={{ mb: 2, display: 'flex', justifyContent: 'space-between' }}>
                      <Chip 
                        label={new Date(plan.departure_date) > new Date() ? "Upcoming" : "Active"} 
                        color={new Date(plan.departure_date) > new Date() ? "info" : "success"} 
                        size="small" 
                        sx={{ mb: 1 }}
                      />
                      <Typography variant="body2" color="text.secondary">
                        Posted {formatDistanceToNow(new Date(plan.created_at || '2025-04-01'), { addSuffix: true })}
                      </Typography>
                    </Box>
                    
                    <Box sx={{ 
                      display: 'flex', 
                      alignItems: 'center', 
                      mb: 1.5, 
                      justifyContent: 'space-between' 
                    }}>
                      <Box sx={{ display: 'flex', alignItems: 'center' }}>
                        <LocationOn color="primary" sx={{ mr: 1 }} />
                        <Typography variant="body1" fontWeight="500">
                          {plan.departure_location}
                        </Typography>
                      </Box>
                      <ArrowForward sx={{ mx: 1, color: 'text.secondary' }} />
                      <Box sx={{ display: 'flex', alignItems: 'center' }}>
                        <LocationOn color="secondary" sx={{ mr: 1 }} />
                        <Typography variant="body1" fontWeight="500">
                          {plan.destination}
                        </Typography>
                      </Box>
                    </Box>
                    
                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2, mb: 1 }}>
                      <Chip 
                        icon={<DateRange fontSize="small" />} 
                        label={`Departs: ${new Date(plan.departure_date).toLocaleDateString()}`} 
                        size="small" 
                        variant="outlined" 
                      />
                      <Chip 
                        icon={<Scale fontSize="small" />} 
                        label={`Up to ${plan.max_weight}kg`} 
                        size="small" 
                        variant="outlined" 
                      />
                    </Box>
                    
                    <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                      Max dimensions: {plan.max_dimensions}
                    </Typography>
                  </CardContent>
                  <CardActions>
                    <Button size="small" color="primary">
                      Edit
                    </Button>
                    <Button size="small" color="primary">
                      View Requests
                    </Button>
                    <Box sx={{ flexGrow: 1 }} />
                    <Tooltip title="Remove this travel plan">
                      <IconButton size="small" color="error">
                        {/* Delete icon would go here */}
                      </IconButton>
                    </Tooltip>
                  </CardActions>
                </Card>
              </Grid>
            ))}
          </Grid>
        )}
      </Box>
      
      {/* Your Item Requests */}
      <Box sx={{ mb: 4 }} data-tour="item-requests">
        <Box sx={{ 
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'center',
          mb: 2
        }}>
          <Typography variant="h5">
            <LocalShipping sx={{ mr: 1, verticalAlign: 'middle' }} />
            Your Item Requests
          </Typography>
          <Button 
            variant="outlined" 
            color="secondary" 
            startIcon={<Add />}
            component={Link}
            to="/request-item"
            size="small"
          >
            New Request
          </Button>
        </Box>
        
        <Divider sx={{ mb: 3 }} />
        
        {displayItemRequests.length === 0 ? (
          <Paper
            elevation={0}
            sx={{
              p: 3,
              textAlign: 'center',
              backgroundColor: 'rgba(211, 98, 44, 0.08)',
              borderRadius: 2,
              border: '1px dashed #d3622c'
            }}
          >
            <NoteAdd sx={{ fontSize: 60, color: 'text.secondary', mb: 1, opacity: 0.7 }} />
            <Typography variant="h6" color="text.secondary" gutterBottom>
              No Item Requests Yet
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
              Need something delivered? Create an item request and find travelers who can help
            </Typography>
            <Button
              variant="contained"
              color="secondary"
              startIcon={<Add />}
              onClick={handleAddItemRequest}
            >
              Create Your First Request
            </Button>
          </Paper>
        ) : (
          <Grid container spacing={3}>
            {displayItemRequests.map((request) => (
              <Grid item xs={12} md={6} key={request.id}>
                <Card sx={{ height: '100%' }}>
                  <CardContent>
                    <Box sx={{ mb: 2, display: 'flex', justifyContent: 'space-between' }}>
                      <Chip 
                        label={request.status === 'open' ? "Open" : request.status} 
                        color={
                          request.status === 'open' ? "success" : 
                          request.status === 'in_progress' ? "info" : 
                          request.status === 'completed' ? "primary" : "default"
                        } 
                        size="small" 
                        sx={{ mb: 1 }}
                      />
                      <Typography variant="body2" color="text.secondary">
                        Needed by {new Date(request.deadline).toLocaleDateString()}
                      </Typography>
                    </Box>
                    
                    <Typography variant="h6" gutterBottom component="div">
                      {request.item_name}
                    </Typography>
                    
                    <Box sx={{ 
                      display: 'flex', 
                      alignItems: 'center', 
                      mb: 1.5,
                      justifyContent: 'space-between' 
                    }}>
                      <Box sx={{ display: 'flex', alignItems: 'center' }}>
                        <LocationOn color="primary" sx={{ mr: 1 }} />
                        <Typography variant="body2">
                          {request.source_location}
                        </Typography>
                      </Box>
                      <ArrowForward sx={{ mx: 1, color: 'text.secondary' }} />
                      <Box sx={{ display: 'flex', alignItems: 'center' }}>
                        <LocationOn color="secondary" sx={{ mr: 1 }} />
                        <Typography variant="body2">
                          {request.destination_location}
                        </Typography>
                      </Box>
                    </Box>
                    
                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2, mb: 1 }}>
                      <Chip 
                        icon={<CardTravel fontSize="small" />} 
                        label={`${request.weight || 2}kg`} 
                        size="small" 
                        variant="outlined" 
                      />
                      <Chip 
                        icon={<Schedule fontSize="small" />} 
                        label={`Deadline: ${new Date(request.deadline).toLocaleDateString()}`} 
                        size="small" 
                        variant="outlined" 
                      />
                    </Box>
                  </CardContent>
                  <CardActions>
                    <Button size="small" color="primary">
                      Edit
                    </Button>
                    <Button size="small" color="primary">
                      View Offers
                    </Button>
                    <Box sx={{ flexGrow: 1 }} />
                    <Tooltip title="Remove this request">
                      <IconButton size="small" color="error">
                        {/* Delete icon would go here */}
                      </IconButton>
                    </Tooltip>
                  </CardActions>
                </Card>
              </Grid>
            ))}
          </Grid>
        )}
      </Box>

      <Box sx={{ mt: 4, display: 'flex', justifyContent: 'center' }}>
        <Button 
          variant="outlined" 
          color="secondary" 
          onClick={() => setRunTour(true)}
          startIcon={<InfoOutlined />}
        >
          Take a Quick Tour
        </Button>
      </Box>

      {isAdmin && (
        <Box sx={{ mt: 4 }} data-tour="admin-panel">
          {/* ... existing admin panel code ... */}
        </Box>
      )}

      {/* Information Dialog */}
      <Dialog
        open={openGuideDialog}
        onClose={handleCloseGuide}
        aria-labelledby="alert-dialog-title"
        aria-describedby="alert-dialog-description"
      >
        <DialogTitle id="alert-dialog-title">
          {"How Global Pickups Works"}
        </DialogTitle>
        <DialogContent>
          <DialogContentText id="alert-dialog-description">
            <Typography variant="subtitle1" gutterBottom fontWeight="bold">Finding the Perfect Match:</Typography>
            <Typography paragraph>
              • <b>As a Traveler:</b> Share your journey details, including departure and destination cities, dates, and how much you can carry.
            </Typography>
            <Typography paragraph>
              • <b>As a Sender:</b> Create item requests with details about what you need delivered, from where to where, and by when.
            </Typography>
            <Typography paragraph>
              Use the search bar to find travelers heading to your destination or senders looking for delivery help along your route.
            </Typography>
            <Typography paragraph>
              When you find a match, you can message each other to discuss details and arrange the pickup and delivery.
            </Typography>
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseGuide} color="primary" autoFocus>
            Got it
          </Button>
        </DialogActions>
      </Dialog>
    </Container>
  );
};

export default Dashboard;